//! Parity tests for the dtype of `filter_unseen_df` results (`tests/fixtures/w9_merge_dtypes.json`,
//! generated by `tests/fixtures/gen_w9_merge_dtypes.py`; `crates/meerschaum-py/PARITY.md` rows 17
//! and 18).
//!
//! The comparison is stricter than the one in `filter_unseen_df.rs`: a column that v4 returns as
//! `object` must be an object column in the kernel, and a column v4 returns typed (`float64`,
//! `str`, `datetime64`, ...) must be a native column of the same logical type. The pandas
//! backends (NumPy, nullable, Arrow-backed) are not distinguished.

mod common;

use common::{cases, compare_values, decode_frame, load_fixture, logical_dtype};
use indexmap::IndexMap;
use meerschaum_kernel::ColumnData;
use meerschaum_kernel::diff::{FilterUnseenOptions, filter_unseen_df};

fn strict_compare(
    expected: &serde_json::Value,
    actual: &meerschaum_kernel::Frame,
) -> Result<(), String> {
    let cols = expected["columns"].as_array().unwrap();
    let names: Vec<String> = cols
        .iter()
        .map(|c| c["name"].as_str().unwrap().to_string())
        .collect();
    if names != actual.names() {
        return Err(format!("columns differ: {names:?} vs {:?}", actual.names()));
    }
    for c in cols {
        let name = c["name"].as_str().unwrap();
        let ev = c["values"].as_array().unwrap();
        let data = &actual.column(name).unwrap().data;
        if ev.len() != data.len() {
            return Err(format!(
                "'{name}': {} rows, expected {}",
                data.len(),
                ev.len()
            ));
        }
        let e_dtype = c["dtype"].as_str().unwrap();
        match (e_dtype == "object", data) {
            (true, ColumnData::Native(s)) => {
                return Err(format!("'{name}': v4 returns object, kernel {}", s.dtype()));
            }
            (false, ColumnData::Object(_)) => {
                return Err(format!("'{name}': v4 returns {e_dtype}, kernel object"));
            }
            (false, ColumnData::Native(_)) => {
                let (e, a) = (
                    logical_dtype(e_dtype, ev),
                    logical_dtype(&data.dtype_str(), &[]),
                );
                if e != a {
                    return Err(format!("'{name}': v4 returns {e_dtype} ({e}), kernel {a}"));
                }
            }
            (true, ColumnData::Object(_)) => {}
        }
        let av: Vec<serde_json::Value> = data.values().iter().map(common::encode).collect();
        for (i, (e, a)) in ev.iter().zip(av.iter()).enumerate() {
            compare_values(e, a).map_err(|m| format!("'{name}' row {i}: {m}"))?;
        }
    }
    Ok(())
}

#[test]
fn merge_dtypes_parity() {
    let fixture = load_fixture("w9_merge_dtypes");
    let all = cases(&fixture);
    assert!(all.len() > 200, "the matrix shrank to {} cases", all.len());
    let mut failures = Vec::new();
    let (mut object_cases, mut typed_cases) = (0, 0);
    for case in all {
        let name = case["name"].as_str().unwrap();
        let old = decode_frame(&case["old"]);
        let new = decode_frame(&case["new"]);
        let dtypes: Option<IndexMap<String, String>> = case["dtypes"].as_object().map(|o| {
            o.iter()
                .map(|(k, v)| (k.clone(), v.as_str().unwrap().to_string()))
                .collect()
        });
        let opts = FilterUnseenOptions {
            dtypes,
            coerce_mixed_numerics: true,
            ..Default::default()
        };
        let out = filter_unseen_df(Some(&old), &new, &opts);
        let v = case["ok"]["columns"]
            .as_array()
            .unwrap()
            .iter()
            .find(|c| c["name"] == "v")
            .unwrap();
        if v["dtype"] == "object" {
            object_cases += 1;
        } else {
            typed_cases += 1;
        }
        if let Err(m) = strict_compare(&case["ok"], &out) {
            failures.push(format!("{name}: {m}"));
        }
    }
    // Guard against a vacuous matrix: both outcomes are well represented.
    assert!(
        object_cases > 40 && typed_cases > 40,
        "{object_cases} object / {typed_cases} typed"
    );
    if !failures.is_empty() {
        panic!(
            "{} of {} merge dtype parity failures:\n{}",
            failures.len(),
            all.len(),
            failures.join("\n")
        );
    }
}

/// PARITY.md row 17: bytes cast to `binary[pyarrow]` by a `bytes` hint merge with the old
/// frame's `object` bytes into an `object` column.
#[test]
fn bytes_hint_against_object_bytes_stays_object() {
    let fixture = load_fixture("w9_merge_dtypes");
    let case = cases(&fixture)
        .iter()
        .find(|c| c["name"] == "obj:bytes|obj:bytes|bytes")
        .expect("row 17 case");
    let out = filter_unseen_df(
        Some(&decode_frame(&case["old"])),
        &decode_frame(&case["new"]),
        &FilterUnseenOptions {
            dtypes: Some(IndexMap::from([
                ("id".to_string(), "int".to_string()),
                ("v".to_string(), "bytes".to_string()),
            ])),
            coerce_mixed_numerics: true,
            ..Default::default()
        },
    );
    assert!(matches!(
        out.column("v").unwrap().data,
        ColumnData::Object(_)
    ));
}

/// PARITY.md row 18: `infer_objects()` makes `object` columns of floats `float64`.
#[test]
fn object_floats_infer_to_float64() {
    let fixture = load_fixture("w9_merge_dtypes");
    for name in ["obj:float|obj:float|None", "obj:float|obj:float|float"] {
        let case = cases(&fixture)
            .iter()
            .find(|c| c["name"] == name)
            .expect(name);
        let dtypes = case["dtypes"].as_object().map(|o| {
            o.iter()
                .map(|(k, v)| (k.clone(), v.as_str().unwrap().to_string()))
                .collect()
        });
        let out = filter_unseen_df(
            Some(&decode_frame(&case["old"])),
            &decode_frame(&case["new"]),
            &FilterUnseenOptions {
                dtypes,
                coerce_mixed_numerics: true,
                ..Default::default()
            },
        );
        assert_eq!(
            out.column("v").unwrap().data.dtype_str(),
            "float64",
            "{name}"
        );
    }
}

/// A cast of an `object` column of floats or decimals to an Arrow integer type truncates toward
/// zero (v4: `Series([2.5, -2.5], dtype=object).astype('int64[pyarrow]')` is `[2, -2]`); a native
/// float column still refuses a fractional value.
#[test]
fn object_floats_truncate_into_arrow_ints() {
    use meerschaum_kernel::Value;
    use meerschaum_kernel::enforce::pandas_astype;
    let object = ColumnData::Object(vec![Value::Float(2.5), Value::Float(-2.5), Value::Null]);
    let casted = pandas_astype("v", &object, "int64[pyarrow]").unwrap();
    assert_eq!(
        casted.values(),
        vec![Value::Int(2), Value::Int(-2), Value::Null]
    );
    let native = meerschaum_kernel::frame::values_to_series(
        "v",
        &[Value::Float(2.5)],
        &polars::prelude::DataType::Float64,
    )
    .unwrap();
    assert!(pandas_astype("v", &ColumnData::Native(native), "int64[pyarrow]").is_err());
}
